\echo '=== V16. LIMPIEZA del volumen: borra pedidos, clientes, conversaciones, handoffs y contactos del rango ficticio y deja intacto el menu ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select restaurantes.demo_limpiar((select id from core.organization where slug = 'los-taquitos-de-pm-demo'), 'volumen');
select (
  (select count(*) from restaurantes.orders where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo'))
  + (select count(*) from restaurantes.customers where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo'))
  + (select count(*) from restaurantes.whatsapp_conversations where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo'))
  + (select count(*) from restaurantes.conversation_handoff where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo'))
  + (select count(*) from restaurantes.callback_requests where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo'))
)::int as restos_del_volumen_deberia_ser_0;
rollback;

\echo '=== V16b. LIMPIEZA del volumen: el menu, la politica y la configuracion del agente de la demo (fila de la organizacion + fila propia de T7) siguen ahi ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select restaurantes.demo_limpiar((select id from core.organization where slug = 'los-taquitos-de-pm-demo'), 'volumen');
select (
  (select count(*) from restaurantes.products where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 279
  and (select count(*) from restaurantes.whatsapp_agent_config where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 2
)::int as configuracion_intacta_deberia_ser_1;
rollback;

\echo '=== V17. LIMPIEZA total: borra la organizacion demo y deja intacta la otra ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select restaurantes.demo_limpiar((select id from core.organization where slug = 'los-taquitos-de-pm-demo'), 'todo');
select (
  (select count(*) from core.organization where slug = 'los-taquitos-de-pm-demo') = 0
  and (select count(*) from restaurantes.orders where organization_id = '00000000-0000-0000-0000-0000000f0002') = 1
)::int as demo_borrada_y_otra_intacta_deberia_ser_1;
rollback;

